let view="home";const $=s=>document.querySelector(s),content=$("#content");const esc=s=>(s||"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));const monthNames=["January","February","March","April","May","June","July","August","September","October","November","December"];function tags(a=[]){return `<div class="tags">${a.map(x=>`<span class="tag">${esc(x)}</span>`).join("")}</div>`}function photo(p){const crop=p.src==="IMG_3334.jpeg"?" crop-packard":"";const whale=/IMG_332[356789]\.jpeg$/.test(p.src)?" whale-card":"";const src=p.src+(p.src.startsWith("IMG_33")?"?v=20261006-1":"");return p?`<figure class="fieldphoto${crop}${whale}"><img src="${esc(src)}" alt="${esc(p.alt||p.caption||'Field note photograph')}" loading="lazy"><figcaption>${esc(p.caption||'')}</figcaption></figure>`:""}function observation(n){const ps=n.photos||[];return `<section class="article-section"><h3>${esc(n.title)}</h3><div class="answer"><p>${esc(n.text)}</p>${(n.links||[]).map(l=>`<p><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label)} ↗</a></p>`).join("")}${n.props?.length?`<div class="prop-guides">${n.props.map(p=>`<details class="nested prop-guide"><summary>${esc(p.name)}</summary><p>${esc(p.intro)}</p>${p.questions.map(q=>`<details class="nested"><summary>${esc(q.q)}</summary><p>${esc(q.answer)}</p></details>`).join("")}<details class="nested"><summary>Spanish prop introduction</summary><p>${esc(p.spanish)}</p></details></details>`).join("")}</div>`:""}${ps.length>1?`<div class="related-images">${ps.map(photo).join("")}</div>`:ps.map(photo).join("")}</div></section>`}function qna(q,i){return `<section class="article-section qna"><div class="eyebrow">Question ${i+1}</div><h3>${esc(q.q)}</h3><div class="answer"><p>${esc(q.short)}</p>${(q.photos||[]).map(photo).join("")}${tags(q.tags)}</div></section>`}function issueArticle(n){return `<article class="card article"><button class="backbtn" data-back="home">← Field Notes home</button><div class="eyebrow">Field Note • ${esc(n.date)}</div><h2>${esc(n.title)}</h2>${n.hero ? `<figure class="fieldphoto"><img src="${esc(n.hero.src)}" alt="${esc(n.hero.alt||n.title)}" loading="eager"><figcaption>${esc(n.hero.caption||"")}</figcaption></figure>` : ""}<div class="statgrid">${n.summary.map(x=>`<div class="stat">${esc(x)}</div>`).join("")}</div><div class="section-heading">🌊 Field observations</div>${n.observations.map(observation).join("")}${(n.highlights||[]).map(h=>`<section class="article-section"><div class="section-heading">🐙 Species Highlight</div><h3>${esc(h.name)}</h3><div class="answer"><p><em>${esc(h.scientific)}</em></p>${h.intro?`<p>${esc(h.intro)}</p>`:""}${h.url?`<a class="linkbtn" href="${esc(h.url)}">Open dedicated species guide →</a>`:""}${(h.facts||[]).map(x=>`<p>• ${esc(x)}</p>`).join("")}${h.topics?.length?`<p><strong>Guide topics:</strong> ${h.topics.map(esc).join(" • ")}</p>`:""}</div></section>`).join("")}${n.highlight?`<section class="article-section"><div class="section-heading">🐙 Species Highlight</div><h3>${esc(n.highlight.name)}</h3><div class="answer"><p><em>${esc(n.highlight.scientific)}</em></p><p>${esc(n.highlight.intro)}</p>${n.highlight.url?`<a class="linkbtn" href="${esc(n.highlight.url)}">Open dedicated species guide →</a>`:""}${n.highlight.facts.map(x=>`<p>• ${esc(x)}</p>`).join("")}<p><strong>Guide topics:</strong> ${n.highlight.topics.map(esc).join(" • ")}</p></div></section>`:""}${n.contacts?.length?`<section class="article-section rescue-contacts"><div class="section-heading">📞 Wildlife Rescue — Important Contacts</div><div class="answer">${n.contacts.map(c=>`<div class="contact-card"><strong>${esc(c.group)}</strong><br>${esc(c.name)}<br><a class="linkbtn compact" href="tel:${esc(c.phone.replace(/[^0-9+]/g,""))}">Call ${esc(c.phone)}</a>${c.note?`<p>${esc(c.note)}</p>`:""}${c.address?`<p>📍 ${esc(c.address)}</p>`:""}</div>`).join("")}</div></section>`:""}${n.qa?.length?`<div class="section-heading">❓ Visitor Q&A</div>${n.qa.map(qna).join("")}`:""}${n.deepDive?`<section class="article-section"><div class="section-heading">🧠 Additional whale facts</div><h3>${esc(n.deepDive.title)}</h3><div class="answer"><p>${esc(n.deepDive.text)}</p>${(n.deepDive.photos||[]).map(photo).join("")}</div></section>`:""}${n.bay?.length?`<details class="note baywatch"><summary>👀 Bay Watch — ${esc(n.date)} (${n.bay.length})</summary><div class="baygrid">${n.bay.map(x=>`<div class="bayitem">• ${esc(x)}</div>`).join("")}</div></details>`:""}</article>`}function dateParts(n){const m=n.id.match(/^(\d{4})-(\d{2})/);return m?{year:m[1],month:monthNames[+m[2]-1]}:{year:"Other",month:"Other"}}function descriptor(n){return [n.title,...n.summary.slice(0,2)].join(" • ")}function latestBlock(){const n=[...FIELD_NOTES].sort((a,b)=>b.id.localeCompare(a.id))[0];return `<details class="index-group latest"><summary>⭐ Latest Field Note</summary><div class="index-body"><div class="eyebrow">${esc(n.date)}</div><h2>${esc(n.title)}</h2><p class="meta">${esc(n.summary.join(" • "))}</p><button class="linkbtn issue-open" data-id="${esc(n.id)}">Read full illustrated note →</button></div></details>`}function archiveBlock(){const groups={};FIELD_NOTES.forEach(n=>{const d=dateParts(n);(((groups[d.year]??={})[d.month]??=[])).push(n)});return `<details class="index-group"><summary>📚 Archive <span>${FIELD_NOTES.length} notes</span></summary><div class="index-body">${Object.keys(groups).sort().reverse().map(y=>`<details class="nested"><summary>${y}</summary>${Object.keys(groups[y]).sort((a,b)=>monthNames.indexOf(a)-monthNames.indexOf(b)).map(m=>`<details class="nested month"><summary>${m}</summary>${groups[y][m].map(n=>`<button class="index-row issue-open" data-id="${esc(n.id)}"><strong>${esc(n.date)}</strong><small>${esc(descriptor(n))}</small></button>`).join("")}</details>`).join("")}</details>`).join("")}</div></details>`}function qaBlock(){const qs=FIELD_NOTES.flatMap(n=>(n.qa||[]).map(q=>({...q,date:n.date,id:n.id})));return `<details class="index-group"><summary>❓ Q&A <span>${qs.length} questions</span></summary><div class="index-body">${qs.length?qs.map(q=>`<button class="index-row issue-open" data-id="${esc(q.id)}"><strong>${esc(q.q)}</strong><small>${esc(q.date)} • ${esc((q.tags||[]).join(" • "))}</small></button>`).join(""):'<p class="meta">No Q&A entries yet.</p>'}</div></details>`}function bayBlock(){const groups={};FIELD_NOTES.forEach(n=>{const d=dateParts(n);(((groups[d.year]??={})[d.month]??=[])).push(n)});return `<details class="index-group"><summary>👀 Bay Watch <span>by date</span></summary><div class="index-body"><p class="meta">Structured weekly sightings retained for a future standalone Bay Watch app.</p>${Object.keys(groups).sort().reverse().map(y=>`<details class="nested"><summary>${y}</summary>${Object.keys(groups[y]).sort((a,b)=>monthNames.indexOf(a)-monthNames.indexOf(b)).map(m=>`<details class="nested month"><summary>${m}</summary>${groups[y][m].map(n=>`<details class="nested week"><summary>${esc(n.date)}</summary><div class="baygrid">${n.bay.map(x=>`<div class="bayitem">• ${esc(x)}</div>`).join("")}</div><button class="textbtn issue-open" data-id="${esc(n.id)}">Open source Field Note →</button></details>`).join("")}</details>`).join("")}</details>`).join("")}</div></details>`}function highlightBlock(){
const hs=FIELD_NOTES.flatMap(n=>[...(n.highlight?[n.highlight]:[]),...(n.highlights||[])].map(highlight=>({id:n.id,date:n.date,highlight})));
const unique=new Map();
hs.forEach(n=>{const key=n.highlight.name.trim().toLocaleLowerCase();if(!unique.has(key))unique.set(key,{name:n.highlight.name,scientific:n.highlight.scientific,url:n.highlight.url,intro:n.highlight.intro||"",facts:n.highlight.facts||[],topics:n.highlight.topics||[],entries:[]});const item=unique.get(key);item.entries.push(n);if(!item.url&&n.highlight.url)item.url=n.highlight.url;if(!item.scientific&&n.highlight.scientific)item.scientific=n.highlight.scientific;if(!item.intro&&n.highlight.intro)item.intro=n.highlight.intro;if(!item.facts?.length&&n.highlight.facts?.length)item.facts=n.highlight.facts;if(!item.topics?.length&&n.highlight.topics?.length)item.topics=n.highlight.topics});
const sorted=[...unique.values()].sort((a,b)=>a.name.localeCompare(b.name,undefined,{sensitivity:"base"}));
const letters=[...new Set(sorted.map(n=>n.name.charAt(0).toUpperCase()))].sort();
return `<details class="index-group species-highlights-index"><summary>🐙 Species Highlights <span>${sorted.length} highlights</span></summary><div class="index-body"><p class="meta">Choose a letter to show only matching species. Tap the same letter again to show all.</p><div class="species-az" role="group" aria-label="Filter Species Highlights by letter">${letters.map(l=>`<button type="button" class="species-letter" data-species-letter="${esc(l)}" aria-pressed="false">${esc(l)}</button>`).join("")}</div><div class="species-list">${sorted.map(n=>`<div class="species-row" data-species-row data-species-first="${esc(n.name.charAt(0).toUpperCase())}"><details class="nested species"><summary>${esc(n.name)}${n.entries.length>1?` <small>(${n.entries.length} notes)</small>`:""}</summary><p><em>${esc(n.scientific||"")}</em></p>${n.intro?`<p>${esc(n.intro)}</p>`:""}${n.facts?.length?`<ul class="species-facts">${n.facts.map(f=>`<li>${esc(f)}</li>`).join("")}</ul>`:""}${n.topics?.length?`<p class="species-topics"><strong>Topics:</strong> ${esc(n.topics.join(" · "))}</p>`:""}${n.name.toLowerCase()==="california sheephead"?`<div class="species-taxonomy"><strong>Taxonomy update:</strong> The February 2026 Field Note reports a change from <em>Semicossyphus pulcher</em> to <em>Bodianus pulcher</em>. The 2026 Catalog of Fishes and World Register of Marine Species accept <em>Bodianus pulcher</em>, although other databases still use <em>Semicossyphus pulcher</em>. The original author's explanation was speculative. <a href="https://researcharchive.calacademy.org/research/ichthyology/catalog/fishcatget.asp?spid=17186" target="_blank" rel="noopener">Catalog of Fishes ↗</a> · <a href="https://www.marinespecies.org/aphia.php?p=taxlist&tName=Semicossyphus" target="_blank" rel="noopener">WoRMS ↗</a></div><figure class="species-photo"><img src="IMG_2883.jpeg" alt="California sheephead female transitioning to male, photographed in the aquarium Kelp Forest exhibit" loading="lazy"><figcaption>California sheephead female transitioning to male — photograph from the earlier Kelp Forest Field Note.</figcaption></figure>`:""}<p class="meta">Field Notes:</p>${n.entries.sort((a,b)=>b.id.localeCompare(a.id)).map(e=>`<button class="textbtn issue-open" data-id="${esc(e.id)}">↳ ${esc(e.date)} →</button>`).join("")}${n.url?`<a class="linkbtn compact sheephead-inline-guide" href="${esc(n.url)}">Open Species Guide →</a>`:""}</details>${n.url?`<a class="linkbtn compact species-open" href="${esc(n.url)}">Open Species Guide →</a>`:""}</div>`).join("")||'<p class="meta">No Species Highlights yet.</p>'}</div></div></details>`;
}
function resourcesBlock(){return `<details class="index-group"><summary>🔗 Resources</summary><div class="index-body"><div class="resource-row"><a href="../inaturalist-citizen-science/index.html"><strong>iNaturalist — credibility &amp; use guidelines</strong></a><small>Volunteer reference · citizen science · Research Grade · identification</small></div>${RESOURCES.map(r=>`<div class="resource-row"><strong>${esc(r)}</strong><small>Link to be connected</small></div>`).join("")}</div></details>`}function home(){return `<section class="home-intro"><h2>Naturalist Field Notes</h2><p>Weekly observations, visitor questions, Bay Watch and species highlights — organized for a growing archive.</p></section>${latestBlock()}${archiveBlock()}${qaBlock()}${bayBlock()}${highlightBlock()}<details class="index-group"><summary>🐋 Gray Whale Skeleton — Steve Webster</summary><div class="index-body"><p class="meta">Historical account, photograph, original Vimeo presentation, visitor Q&A, science and transcript.</p><a class="linkbtn" href="../gray-whale/index.html">Open Gray Whale Species Guide →</a></div></details>${resourcesBlock()}`}function render(){const q=$("#search").value.trim().toLowerCase();if(q)return renderSearch(q);content.innerHTML=home();bind()}function bind(){document.querySelectorAll(".species-highlights-index").forEach(directory=>{let selected=null;const buttons=[...directory.querySelectorAll("[data-species-letter]")];const rows=[...directory.querySelectorAll("[data-species-row]")];buttons.forEach(button=>button.addEventListener("click",()=>{const letter=button.dataset.speciesLetter;selected=selected===letter?null:letter;buttons.forEach(b=>{const active=b.dataset.speciesLetter===selected;b.setAttribute("aria-pressed",String(active));b.classList.toggle("selected",active)});rows.forEach(row=>{row.hidden=Boolean(selected&&row.dataset.speciesFirst!==selected)})}))});document.querySelectorAll(".issue-open").forEach(b=>b.onclick=()=>openIssue(b.dataset.id));document.querySelectorAll("[data-back]").forEach(b=>b.onclick=()=>{$("#search").value="";render();window.scrollTo(0,0)})}function openIssue(id){const n=FIELD_NOTES.find(x=>x.id===id);if(!n)return;content.innerHTML=issueArticle(n);bind();window.scrollTo(0,0)}function renderSearch(q){const notes=FIELD_NOTES.filter(n=>JSON.stringify(n).toLowerCase().includes(q));const referenceMatch=["inaturalist","citizen science","credibility","research grade","species identification","scientific sources","volunteer reference"].some(t=>t.includes(q)||q.includes(t));content.innerHTML=`<div class="search-results"><div class="eyebrow">Search</div><h2>Results for “${esc(q)}”</h2><p class="meta">${notes.length} matching Field Note${notes.length===1?'':'s'}</p></div>`+(referenceMatch?`<a class="index-row" href="../inaturalist-citizen-science/index.html"><strong>Volunteer Reference — iNaturalist credibility &amp; use guidelines</strong><small>Citizen science • Research Grade • identification • scientific sources</small></a>`:"")+(notes.length?notes.map(n=>`<button class="index-row issue-open" data-id="${esc(n.id)}"><strong>${esc(n.date)} — ${esc(n.title)}</strong><small>${esc(n.summary.join(" • "))}</small></button>`).join(""):`<div class="empty">No matching Field Notes.</div>`);bind()}$("#search").addEventListener("input",render);$("#clearSearch").onclick=()=>{$("#search").value="";render()};$("#clearCache").onclick=async()=>{if("caches" in window){for(const k of await caches.keys())await caches.delete(k)}if("serviceWorker" in navigator){for(const reg of await navigator.serviceWorker.getRegistrations()){if(reg.scope.includes("/naturalist-field-notes/"))await reg.unregister()}}const url=new URL(location.href);url.searchParams.set("refresh",Date.now().toString());location.replace(url.href)};const offlineBadge=document.getElementById("offlineStatus");function offlineState(state,done,total){if(!offlineBadge)return;offlineBadge.className="offline-status "+state;if(state==="ready")offlineBadge.textContent="🟢 Field Notes Offline Ready — v0.34";else if(state==="updating")offlineBadge.textContent="🟡 Preparing offline files"+(total?" · "+done+"/"+total:"");else if(state==="incomplete")offlineBadge.textContent="🔴 Offline update incomplete — reconnect to Wi-Fi";else offlineBadge.textContent="🟡 Checking offline readiness…"}
offlineState("checking");
if("serviceWorker" in navigator){navigator.serviceWorker.addEventListener("message",event=>{const m=event.data;if(m?.kind==="offline-status")offlineState(m.type,m.done,m.total)});window.addEventListener("load",async()=>{try{const reg=await navigator.serviceWorker.register("./sw.js",{scope:"./"});const check=()=>{const worker=reg.installing||reg.waiting||reg.active||navigator.serviceWorker.controller;if(worker)worker.postMessage({type:"GET_OFFLINE_STATUS"})};check();if(reg.installing){offlineState("updating",0,135);reg.installing.addEventListener("statechange",()=>{if(reg.installing?.state==="redundant")offlineState("incomplete");else check()})}navigator.serviceWorker.addEventListener("controllerchange",check);setTimeout(check,1500)}catch(e){offlineState("incomplete");console.warn("Offline mode unavailable:",e)}})}else offlineState("incomplete");render();
// Deep-link directly to a specific published Field Note (used by emergency contact cards).
const directNote=new URLSearchParams(window.location.search).get("note");
if(directNote&&FIELD_NOTES.some(n=>n.id===directNote))openIssue(directNote);

:root{--ink:#14333d;--muted:#60777e;--sea:#073b4c;--foam:#eef8f7;--line:#d6e5e5;--card:#fff;--accent:#118a8a;--sand:#f8f5ed}*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;color:var(--ink);background:#f5f8f8}.topbar{background:var(--sea);color:white;padding:max(12px,env(safe-area-inset-top)) 16px 16px;position:sticky;top:0;z-index:5;box-shadow:0 2px 10px #0002}.hub{color:#d8f4f2;text-decoration:none;font-size:.92rem;font-weight:650}.title{display:flex;gap:10px;align-items:center;margin-top:10px}.mark{font-size:2rem}h1{font-size:1.3rem;margin:0}.title p{font-size:.78rem;margin:3px 0 0;color:#d8eeee}main{max-width:760px;margin:auto;padding:14px}.searchbox{display:flex;background:white;border:1px solid var(--line);border-radius:14px;overflow:hidden;box-shadow:0 2px 8px #0001;margin-bottom:12px}.searchbox input{flex:1;border:0;padding:13px;font-size:16px;outline:none}.searchbox button{border:0;background:white;padding:0 15px;font-size:24px;color:var(--muted)}.home-intro{padding:4px 2px 8px}.home-intro h2{margin:0 0 4px}.home-intro p{margin:0;color:var(--muted);font-size:.9rem;line-height:1.4}.index-group{background:var(--card);border:1px solid var(--line);border-radius:14px;margin:9px 0;box-shadow:0 2px 8px #0000000b;overflow:hidden}.index-group>summary{padding:15px;font-size:1rem;font-weight:800;cursor:pointer;list-style-position:inside}.index-group>summary span{float:right;color:var(--muted);font-size:.74rem;font-weight:600;padding-top:3px}.index-group[open]>summary{background:var(--foam);border-bottom:1px solid var(--line)}.index-body{padding:12px}.nested{border-bottom:1px solid var(--line);padding:0}.nested:last-child{border-bottom:0}.nested>summary{padding:11px 4px;font-weight:750;cursor:pointer}.nested.month>summary{padding-left:14px}.nested.week,.nested.species{padding-left:14px}.nested.week .baygrid{padding:5px 5px 12px}.index-row{display:block;width:100%;text-align:left;border:0;border-top:1px solid var(--line);background:white;padding:12px 5px;color:var(--ink);font:inherit;cursor:pointer}.index-row:first-of-type{border-top:0}.index-row strong,.index-row small{display:block}.index-row strong{font-size:.9rem}.index-row small,.resource-row small{color:var(--muted);font-size:.76rem;line-height:1.35;margin-top:4px}.resource-row{padding:10px 4px;border-bottom:1px solid var(--line)}.resource-row strong,.resource-row small{display:block}.latest .index-body{background:linear-gradient(135deg,#eaf8f6,#fff)}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;margin:12px 0;padding:16px;box-shadow:0 2px 9px #0000000c}.eyebrow{font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);font-weight:800}h2{font-size:1.2rem;margin:5px 0 10px}h3{font-size:1.02rem;margin:0 0 8px}.meta{font-size:.82rem;color:var(--muted);line-height:1.4}.statgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0 18px}.stat{background:#f3f8f8;padding:10px;border-radius:11px;font-size:.9rem}.section-heading{font-size:.88rem;font-weight:850;color:var(--sea);text-transform:uppercase;letter-spacing:.04em;border-bottom:2px solid var(--line);padding:15px 0 7px;margin:4px 0 0}.article-section{padding:16px 0;border-bottom:1px solid var(--line)}.qna{background:#fbfdfd;margin:0 -5px;padding:16px 5px}.answer{line-height:1.5;color:#294851}.answer p{margin:.7em 0}.fieldphoto{margin:12px 0 16px}.fieldphoto img{display:block;width:100%;height:auto;border-radius:12px;border:1px solid var(--line);background:#eef3f3}.fieldphoto figcaption{font-size:.8rem;line-height:1.35;color:var(--muted);padding:6px 3px 0}.tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.tag{font-size:.7rem;padding:4px 7px;border-radius:999px;background:var(--foam);color:#35666a}details.note{border-top:1px solid var(--line);padding:13px 0}summary{font-weight:750}.baygrid{columns:2;column-gap:20px;padding-top:10px}.bayitem{break-inside:avoid;padding:4px 0;font-size:.9rem}.linkbtn,.textbtn,.backbtn{display:inline-block;border:0;border-radius:10px;font-weight:700;cursor:pointer}.linkbtn{margin-top:8px;padding:9px 12px;background:var(--sea);color:white;text-decoration:none;font-size:.86rem}.linkbtn.compact{margin:8px 0 12px}.textbtn{background:transparent;color:var(--accent);padding:8px 0;text-align:left}.backbtn{background:var(--foam);color:var(--sea);padding:8px 10px;margin-bottom:13px}.secondary{border:1px solid var(--line);background:white;padding:9px 12px;border-radius:10px}.empty{text-align:center;color:var(--muted);padding:35px 10px}.search-results{padding:5px 2px 10px}footer{max-width:760px;margin:auto;padding:8px 14px 30px;color:var(--muted);font-size:.84rem}.version{text-align:center;font-size:.74rem}@media(max-width:430px){.baygrid{columns:1}.statgrid{grid-template-columns:1fr}.card{padding:13px}.fieldphoto{margin:10px 0 14px}.article-section{padding:14px 0}.index-group>summary{padding:14px 12px}}
.related-images{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:10px}.related-images .fieldphoto{margin:0 0 8px}.related-images .fieldphoto img{height:auto}@media(max-width:430px){.related-images{grid-template-columns:1fr 1fr;gap:7px}.related-images .fieldphoto figcaption{font-size:.72rem}}

/* Crop the supplied R/V David Packard screenshot to the photograph area. */
.fieldphoto.crop-packard{overflow:hidden}
.fieldphoto.crop-packard img{width:100%;aspect-ratio:1.48/1;object-fit:cover;object-position:center top}

/* Sept 3–9 source-image display corrections: preserve user crop on whale cards and remove screenshot framing around Packard. */
.fieldphoto.whale-card{overflow:hidden}
.fieldphoto.whale-card img{display:block;width:100%;aspect-ratio:1/1;object-fit:cover;object-position:center top}
.fieldphoto.crop-packard{overflow:hidden}
.fieldphoto.crop-packard img{display:block;width:100%;height:auto;aspect-ratio:auto;clip-path:inset(0 0 7% 0)}

/* Verified offline package status */
.offline-status{margin:0 0 12px;padding:10px 13px;border-radius:11px;font-size:.9rem;font-weight:700;border:1px solid #d2dfe1;background:#edf4f5;color:#25444b}
.offline-status.ready{background:#e7f5e8;border-color:#a9d8b0;color:#175b2c}
.offline-status.updating,.offline-status.checking{background:#fff7df;border-color:#ecd393;color:#6c500c}
.offline-status.incomplete{background:#fff0ef;border-color:#edb4b0;color:#8a2522}

/* Species Highlights: Animals directory letter filtering, visible guide access */
.species-az{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0 12px}.species-letter{min-width:38px;min-height:38px;border:1px solid #bed6d8;border-radius:8px;background:#eff7f7;color:#164850;font-weight:750;cursor:pointer}.species-letter.selected,.species-letter[aria-pressed="true"]{background:#087f84;color:#fff;border-color:#087f84}.species-letter:focus-visible{outline:3px solid #087f84;outline-offset:2px}.species-row{display:flex;gap:9px;align-items:center;justify-content:space-between;padding:7px 2px;border-top:1px solid var(--line)}.species-row[hidden]{display:none!important}.species-row>.species{flex:1;min-width:0;margin:0}.species-row>.species>summary{overflow-wrap:anywhere;cursor:pointer}.species-row>.species-open{flex-shrink:0;margin:0;font-size:.8rem;padding:8px 9px;white-space:nowrap}@media(max-width:420px){.species-row>.species-open{font-size:.72rem;padding:8px 6px}}

/* Restored Species Highlight details and source image */
.species-facts{padding-left:20px;margin:8px 0}.species-facts li{margin:5px 0}.species-topics{font-size:.86rem;color:var(--muted)}.species-taxonomy{padding:12px;margin:12px 0;background:#eaf5f4;border-left:4px solid #087f84;border-radius:7px;font-size:.88rem;line-height:1.5}.species-taxonomy a{color:#075d75}.species-photo{margin:12px 0}.species-photo img{display:block;max-width:100%;width:auto;height:auto;border-radius:10px;border:1px solid var(--line)}.species-photo figcaption{font-size:.8rem;color:var(--muted);padding:5px 0}

/* California sheephead: show full photo, original aspect ratio, modest size */
.species-highlights-index .species-photo{margin:12px auto;max-width:100%;width:max-content;text-align:center}
.species-highlights-index .species-photo img{display:block;width:auto;height:auto;max-width:min(100%,420px);max-height:320px;object-fit:contain;margin:0 auto;border-radius:10px}
.species-highlights-index .species-photo figcaption{max-width:420px;margin:0 auto;text-align:left}

/* Guide link available both in the collapsed species row and expanded detail */
.species-highlights-index .species-row>.species-open{display:inline-flex!important;align-items:center;justify-content:center;visibility:visible!important;opacity:1!important;min-height:38px;background:#087f84;color:#fff;text-decoration:none;position:relative;z-index:1}
.species-highlights-index .sheephead-inline-guide{display:inline-block!important;margin:12px 0;color:#fff}

